// Original, synthesized school sounds. No recording or external audio files.
export class SchoolAudio {
 constructor(makeContext){this.makeContext=makeContext||(()=>{const A=globalThis.AudioContext||globalThis.webkitAudioContext;return A?new A():null;});this.context=null;this.master=null;this.enabled=false;this.volume=.4;this.hidden=false;this.lastStep=-100;this.lastAmbient=-100;}
 configure({sound=false,volume=40}={}){this.enabled=!!sound;this.volume=Math.max(0,Math.min(100,Number(volume)||0))/100;this.updateGain();}
 updateGain(){if(this.master){const t=this.context.currentTime;this.master.gain.cancelScheduledValues(t);this.master.gain.setValueAtTime(this.enabled&&!this.hidden?this.volume:0,t);}}
 unlock(){if(!this.enabled||this.hidden)return false;try{if(!this.context){this.context=this.makeContext();if(!this.context)return false;this.master=this.context.createGain();this.master.connect(this.context.destination);this.updateGain();}if(this.context.state==='suspended')this.context.resume()?.catch?.(()=>{});return true;}catch{return false;}}
 visibility(hidden){this.hidden=!!hidden;this.updateGain();}
 tone(frequency,delay=0,duration=.2,type='sine',level=.12){if(!this.enabled||this.hidden||!this.context||!this.master)return false;const a=this.context,start=a.currentTime+delay,osc=a.createOscillator(),gain=a.createGain();osc.type=type;osc.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(Math.max(.0002,level),start+.012);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(gain);gain.connect(this.master);osc.onended=()=>{osc.disconnect();gain.disconnect();};osc.start(start);osc.stop(start+duration+.03);return true;}
 play(kind='tap'){if(!this.enabled||this.hidden||!this.context)return false;const now=this.context.currentTime;if(kind==='step'){if(now-this.lastStep<.31)return false;this.lastStep=now;return this.tone(95,0,.065,'triangle',.025);}
 const sounds={tap:[[540,0,.09]],message:[[659,0,.15],[880,.15,.27]],bell:[[784,0,.4],[659,.42,.4],[698,.84,.4],[523,1.26,.65]],success:[[523,0,.16],[659,.13,.16],[784,.26,.4]],tool:[[220,0,.1],[330,.07,.14]],paper:[[1250,0,.045],[950,.04,.045]]};
 for(const [frequency,delay,duration] of sounds[kind]||sounds.tap)this.tone(frequency,delay,duration,kind==='tool'?'triangle':'sine',kind==='bell'?.12:.075);return true;}
 note(index,instrument='piano'){const notes=[261.63,293.66,329.63,349.23,392,440,493.88,523.25];if(!Number.isInteger(index)||!notes[index]||!['piano','bell','drum'].includes(instrument))return false;if(instrument==='drum')return this.tone(85+index*15,0,.16,'triangle',.24);const ok=this.tone(notes[index],0,instrument==='bell'?.8:.55,'sine',.16);if(ok&&instrument==='piano')this.tone(notes[index]*2,0,.25,'triangle',.025);return ok;}
 ambience(active){if(!active||!this.enabled||this.hidden||!this.context)return;const now=this.context.currentTime;if(now-this.lastAmbient<8)return;this.lastAmbient=now;const notes=Math.floor(now/8)%2?[293.66,369.99,440]:[261.63,329.63,392];notes.forEach((n,i)=>this.tone(n,i*.34,1.7,'sine',.015));}
}
